import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

// Хайлтад юу ч тохирсонгүй — жагсаалт одоогоор хоосон.
const RESULTS = [];

function App() {
  // энд бичнэ үү: FlatList-д ListEmptyComponent нэмж "Илэрц алга" харуул
  return (
    <FlatList
      style={styles.list}
      data={RESULTS}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, backgroundColor: "#f8fafc" },
  empty: { padding: 48, alignItems: "center" },
  emptyText: { fontSize: 18, color: "#94a3b8", fontWeight: "600" },
  row: { padding: 16, backgroundColor: "#fff" },
  name: { fontSize: 16 },
});

registerRootComponent(App);

import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

// Хайлтад юу ч тохирсонгүй — жагсаалт одоогоор хоосон.
const RESULTS = [];

function App() {
  return (
    <FlatList
      style={styles.list}
      data={RESULTS}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
        </View>
      )}
      ListEmptyComponent={
        <View nativeID="empty" style={styles.empty}>
          <Text style={styles.emptyText}>Илэрц алга</Text>
        </View>
      }
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, backgroundColor: "#f8fafc" },
  empty: { padding: 48, alignItems: "center" },
  emptyText: { fontSize: 18, color: "#94a3b8", fontWeight: "600" },
  row: { padding: 16, backgroundColor: "#fff" },
  name: { fontSize: 16 },
});

registerRootComponent(App);
